def f(blocks: List[List[str]]):
    import re
    import collections

    def evaluate(expression):
        def op(t):
            if t == 'plus':
                return lambda a, b: a + b
            elif t =='minus':
                return lambda a, b: a - b
            elif t =='mul':
                return lambda a, b: a * b
            elif t == 'exp':
                return lambda a, b: a ** b

        ops = collections.deque()
        nums = collections.deque()

        items = re.findall(r'(\d+|\+|\-|\*|\^|\(|\))', expression)

        def apply_op(op_func, num):
            while ops:
                last_op = ops[-1]
                if last_op not in ['(', '+', '-'] or \
                    (op_func == '-' and last_op == '-') or \
                    op_func in ['*', '^'] and last_op in ['*', '^']:
                    nums.append(ops.pop())
                    nums.append(op(op_func)(nums.pop(), nums.pop()))
                else:
                    if last_op == '(' and op_func == '-':
                        nums.append('0')
                    break
            ops.append(num)

        for item in items:
            if re.match(r'\d+', item):
                if len(nums) > 0 and isinstance(nums[-1], int):
                    apply_op('+', item)
                else:
                    nums.append(int(item))
            elif item == '-':
                item = '+'  # Reduced to Plus
                apply_op(item, item)
            elif item in ['+', '-', '*', '^']:
                apply_op(item, item)
            elif item == '(':
                ops.append(item)
            elif item == ')':
                while ops[-1]!= '(':
                    nums.append(ops.pop())
                    apply_op('+', '+')
                if len(nums) > 1:
                    nums.append(ops.pop())
                    apply_op('+', '+')

        while len(nums) > 0:
            apply_op('+', '+')

        assert len(ops) == 0   # Matching parenthesis

        return nums[0]

    result = []
    for block in blocks:
        curr_result = []
        for line in block:
            postfix = []
            for ch in line:
                if re.match(r"[a-zA-Z0-9]", ch):
                    postfix.append(ch)
                elif ch == '^':
                    postfix.append(ch)
                elif ch == "+":
                    while len(postfix) and postfix[-1] in ['+', '-', '*', '^']:
                        curr_result.append(postfix.pop())
                    postfix.append(ch)
                elif ch == '-':
                    while len(postfix) and postfix[-1] in ['+', '-', '*', '^']:
                        curr_result.append(postfix.pop())
                    postfix.append(ch)
                elif ch == '*':
                    while len(postfix) and postfix[-1] in ['*', '^']:
                        curr_result.append(postfix.pop())
                    postfix.append(ch)
                elif ch == '/':
                    while len(postfix) and postfix[-1] in ['*', '^']:
                        curr_result.append(postfix.pop())
                    postfix.append(ch)
                elif ch == '(':
                    postfix.append(ch)
                elif ch == ')':
                    while postfix[-1]!= '(':
                        curr_result.append(postfix.pop())
                    postfix.pop()
            while len(postfix):
                curr_result.append(postfix.pop())
            curr_result =''.join(curr_result)
            if len(curr_result) > 0:
                curr_result = str(evaluate(curr_result))
            curr_result = curr_result * len(block)
            if curr_result > 0:
                curr_result = int(curr_result)
            result.append(curr_result)
        result.append>.</br>

    return "\n".join(map(str, result))
